/*
 * A258047  Sequence (d(n)) generated by Rule 3 (in Comments) with a(1) = 1
 *          and d(1) = 0.
 * https://oeis.org/A258047
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, sign
 * Formula:   not stated
 * Range:     i8 n <= 96, i16 n <= 1000, i32 n <= 1000, i64 n <= 1000,
 *            i128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A258047 (d(n)) generated by Rule 3. */
/* a(1) = 1, d(1) = 0.  Return d(n) for n ≥ 1. */

#include <stdlib.h>
#include <stdbool.h>

/* Static state for memoisation */
static seq_t *a_vals = NULL;      /* a(k) values, 1‑indexed */
static seq_t *d_vals = NULL;      /* d(k) values, 1‑indexed */
static size_t  cap   = 0;         /* current capacity of the arrays */
static size_t  len   = 0;         /* number of terms already computed */

/* Linear search for membership; sufficient for n ≤ 10 000 */
static inline bool contains(const seq_t *arr, size_t l, seq_t v)
{
    for (size_t i = 0; i < l; ++i)
        if (arr[i] == v)
            return true;
    return false;
}

/* Ensure arrays have at least 'need' slots. */
static void ensure_capacity(size_t need)
{
    if (cap >= need)
        return;
    size_t new_cap = cap ? (cap << 1) : 64;
    while (new_cap < need)
        new_cap <<= 1;
    seq_t *na = (seq_t *)realloc(a_vals, new_cap * sizeof(seq_t));
    seq_t *nd = (seq_t *)realloc(d_vals, new_cap * sizeof(seq_t));
    if (!na || !nd) exit(1);           /* out of memory */
    a_vals = na;
    d_vals = nd;
    cap    = new_cap;
}

/* Initialisation with a(1)=1, d(1)=0. */
static void init_sequence(void)
{
    if (len > 0) return;              /* already initialised */
    ensure_capacity(1);
    a_vals[0] = (seq_t)1;
    d_vals[0] = (seq_t)0;
    len = 1;
}

/* Compute the sequence up to index n (1‑based). */
static void compute_up_to(idx_t n)
{
    while (len < (size_t)n) {
        seq_t a_k = a_vals[len-1];

        /* ---- Step 1: find least negative h in (1 - a_k, 0) ---- */
        seq_t h;
        seq_t min_neg = (seq_t)2 - a_k;   /* 1 - a_k + 1, first allowed integer > 1 - a_k */
        bool found = false;
        for (h = min_neg; h <= -1; ++h) {   /* iterate from more negative to -1 */
            if (!contains(d_vals, len, h) && !contains(a_vals, len, a_k + h)) {
                found = true;
                break;
            }
        }
        if (found) {
            ensure_capacity(len + 1);
            a_vals[len] = a_k + h;
            d_vals[len] = h;
            ++len;
            continue;                    /* stay in Step 1 */
        }

        /* ---- Step 2: smallest positive h not in D(k) with a_k - h not in A(k) ---- */
        for (h = 1; ; ++h) {
            if (!contains(d_vals, len, h) && !contains(a_vals, len, a_k - h)) {
                ensure_capacity(len + 1);
                a_vals[len] = a_k + h;
                d_vals[len] = h;
                ++len;
                break;                    /* after Step 2 go back to Step 1 */
            }
        }
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;            /* undefined for n = 0 */
    init_sequence();
    compute_up_to(n);
    return d_vals[n-1];                     /* d(n) */
}
